begin;

update public.spell_catalog set name_ru='Опаляющий луч Аганаззара', effect_summary='Из тебя вырывается линия пламени длиной 30 футов и шириной 5 футов. Каждое существо в линии делает спасбросок Ловкости: при провале получает 3к8 огненного урона, при успехе — половину.', author_description='Прямой огненный резак: не шар и не конус, а аккуратная полоса через тех, кто неудачно выстроился в линию.', author_comment='Иногда геометрия боя важнее размера кости урона.', upcast='Урон увеличивается на 1к8 за каждый уровень ячейки выше 2.', notes='Линия начинается от тебя; существа на ней совершают спасбросок Ловкости.', casting_time='1 действие' where slug='aganazzar-s-scorcher' and source_kind='official';

update public.spell_catalog set name_ru='Воздушный пузырь', effect_summary='Вокруг головы добровольного существа в пределах 60 футов создаётся сфера свежего воздуха на 24 часа, позволяющая нормально дышать там, где это иначе невозможно.', author_description='Космос, вода, дымная шахта — маленький пузырь решает очень большую проблему: необходимость дышать.', author_comment='Редкая магия, ценность которой становится очевидной ровно в тот момент, когда воздуха больше нет.', upcast='Ячейкой 3 уровня или выше создаёшь ещё 2 пузыря за каждый уровень ячейки выше 2.', notes='На многоголовом существе достаточно пузыря вокруг одной головы, если дыхательная система общая.', casting_time='1 действие' where slug='air-bubble' and source_kind='official';

update public.spell_catalog set name_ru='Заимствованное знание', effect_summary='Выбираешь один навык, которым не владеешь. На 1 час получаешь владение этим навыком; эффект заканчивается раньше, если снова сотворишь это заклинание.', author_description='На час магия делает вид, что ты действительно учился этому ремеслу. Очень удобно перед одной конкретной задачей, к которой никто в группе не готовился.', author_comment='Диплом на час — всё ещё диплом, если проверка уже сейчас.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Нельзя выбрать навык, которым ты уже владеешь. Повторное сотворение прекращает предыдущий эффект.', casting_time='1 действие' where slug='borrowed-knowledge' and source_kind='official';

update public.spell_catalog set name_ru='Доспех смерти', effect_summary='Касаешься существа и на 1 час окружаешь его тёмной аурой. Цель получает преимущество на спасброски от смерти; раз за ход, когда существо в пределах 5 футов попадает по ней рукопашной атакой, нападающий получает 2к4 некротического урона.', author_description='Нечестиво практичный бафф для того, кто собирается стоять лицом к врагу и собирать удары. Чем чаще его бьют, тем чаще враги жалеют об этом.', author_comment='Броня, которая не мешает получить удар — она просто выставляет счёт после него.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Материальный компонент: оникс стоимостью 50+ зм, который расходуется. Урон ауры срабатывает не чаще одного раза за ход.', casting_time='1 действие' where slug='death-armor' and source_kind='official';

update public.spell_catalog set name_ru='Услужливые гомункулы Дерьяна', effect_summary='Призываешь на 8 часов группу неуязвимых нематериальных духов-гомункулов. Они владеют Арканой и выбранными при сотворении ремесленными инструментами; при изготовлении предмета работают как один помощник и вдвое сокращают время твоего изготовления.', author_description='Магическая артель, которая появляется, помогает работать и не просит перерыв на обед. Главная специализация — крафт, а не бой.', author_comment='Самый дорогой способ услышать: «Я помогу подержать». Зато держат профессионально.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Можно сотворять ритуалом. Требуются порошковые самоцветы стоимостью 100+ зм, которые расходуются, и набор ремесленных инструментов, которым ты владеешь.', casting_time='1 действие или ритуал' where slug='deryan-s-helpful-homunculi' and source_kind='official';

update public.spell_catalog set name_ru='Пылевой вихрь', effect_summary='Создаёшь вихрь в кубе 5 футов. Существо, закончившее ход в пределах 5 футов от него, делает спасбросок Силы: при провале получает 1к8 дробящего урона и отталкивается на 10 футов, при успехе — половину без толчка. Бонусным действием вихрь можно перемещать до 30 футов.', author_description='Маленький управляемый смерч: немного урона, немного контроля и много песка там, где песок вообще есть.', author_comment='Если враг говорит, что ветер не оружие, отправь к нему этот ветер.', upcast='Урон увеличивается на 1к8 за каждый уровень ячейки выше 2.', notes='Требуется концентрация. Над песком, землёй или пылью вихрь поднимает облако, которое временно сильно заслоняет область вокруг него.', casting_time='1 действие' where slug='dust-devil' and source_kind='official';

update public.spell_catalog set name_ru='Привязка к земле', effect_summary='Одно существо в пределах 300 футов делает спасбросок Силы. При провале его скорость полёта становится 0 на время концентрации; если оно было в воздухе, оно безопасно снижается со скоростью до 60 футов за раунд, пока не окажется на земле.', author_description='Очень специализированное, но очень убедительное «спускайся сюда». Дракону, гарпии или летающему магу внезапно приходится уважать наземную часть карты.', author_comment='Не наносит урон. Просто отменяет главную причину, по которой цель чувствовала себя особенной.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация до 1 минуты. Спуск не считается обычным падением, пока заклинание действует.', casting_time='1 действие' where slug='earthbind' and source_kind='official';

update public.spell_catalog set name_ru='Ускользание Эльминстера', effect_summary='Бонусным действием создаёшь на себе защитные чары до 10 минут с концентрацией. Получаешь преимущество на спасброски против заклинаний и магических эффектов; если успешно проходишь такой спасбросок и обычно получил бы половину урона, вместо этого не получаешь урона вовсе.', author_description='Небольшой персональный режим «магия? нет, спасибо». Особенно неприятен для противников, привыкших рассчитывать хотя бы на половину урона после успешного спасброска.', author_comment='Эльминстер не уклоняется от проблем. Проблемы просто промахиваются магией.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Эффект работает только там, где есть спасбросок против заклинания или магического эффекта.', casting_time='1 бонусное действие' where slug='elminster-s-elusion' and source_kind='official';

update public.spell_catalog set name_ru='Стая фамильяров', effect_summary='На срок до 1 часа с концентрацией призываешь трёх фамильяров одинаковой природы: небожителей, фей или исчадий. Они действуют по правилам фамильяра, поддерживают телепатию и передачу чувств в пределах 1 мили; через одного из них за ход можно передать заклинание касанием.', author_description='Один фамильяр — разведчик. Три фамильяра — уже отдел наблюдения, связи и доставки магии.', author_comment='Когда одного магического питомца недостаточно, решение очевидно: сделать проблему коллективной.', upcast='За каждый уровень ячейки выше 2 призывается ещё один фамильяр.', notes='Если у тебя уже есть фамильяр от аналогичного эффекта, это заклинание создаёт на одного меньше. Все призванные им фамильяры должны иметь одинаковую природу.', casting_time='1 минута' where slug='flock-of-familiars' and source_kind='official';

update public.spell_catalog set name_ru='Благосклонность удачи', effect_summary='Даруешь существу в пределах 60 футов частицу удачи на 1 час. Оно может израсходовать её, чтобы после своей атаки, проверки или спасброска бросить ещё один к20 и выбрать результат; либо когда по нему попадают атакой, заставить бросить дополнительный к20 и выбрать, какой результат атаки используется.', author_description='Ты заранее покупаешь право однажды сказать судьбе: «Нет, этот бросок меня не устраивает». Очень сильная страховка для одного действительно важного момента.', author_comment='Удача любит подготовленных. И жемчуг за сто золотых.', upcast='За каждый уровень ячейки выше 2 можно выбрать ещё одно существо.', notes='Материальный компонент — белая жемчужина стоимостью 100 зм, которая расходуется для каждой цели. Частица исчезает после использования.', casting_time='1 минута' where slug='fortune-s-favor' and source_kind='official';

update public.spell_catalog set name_ru='Дар красноречия', effect_summary='Реакцией сразу после того, как ты что-то сказал существу, меняешь память слушателей в пределах 5 футов: выбранные существа забывают всё, что услышали от тебя за последние 6 секунд, и вместо этого помнят слова, произнесённые как вербальный компонент заклинания.', author_description='Магическая кнопка «я этого не говорил». Идеальна для переговоров, на которых рот успел принять решение раньше мозга.', author_comment='Лучший способ исправить оговорку — переписать последние шесть секунд свидетелям.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Реакция срабатывает именно после твоих слов. Требуется лицензионный компонент 2 зм, который расходуется.', casting_time='1 реакция, когда ты говоришь с другим существом' where slug='gift-of-gab' and source_kind='official';

update public.spell_catalog set name_ru='Исцеляющий дух', effect_summary='Призываешь духа в кубе 5 футов в пределах 60 футов на срок до 1 минуты с концентрацией. Когда видимое тобой существо впервые за ход входит в пространство духа или начинает там ход, ты можешь восстановить ему 1к6 хитов. Дух способен исцелить ограниченное число раз, после чего исчезает.', author_description='Маленькая передвижная точка первой помощи. Её можно поставить на проходе или переносить бонусным действием туда, где здоровье особенно быстро заканчивается.', author_comment='Лечебный дух работает как хороший медик: помогает многим, но ресурс всё-таки считает.', upcast='Лечение увеличивается на 1к6 за каждый уровень ячейки выше 2.', notes='Число срабатываний равно 1 + модификатор твоей заклинательной характеристики, минимум 2. Бонусным действием дух можно переместить до 30 футов.', casting_time='1 бонусное действие' where slug='healing-spirit' and source_kind='official';

update public.spell_catalog set name_ru='Гомункул-слуга', effect_summary='За 1 час или ритуалом призываешь особого Крошечного конструкта-гомункула в пределах 10 футов. Он действует сразу после тебя на твоей инициативе, выполняет команды без затрат твоего действия, умеет атаковать силовой энергией и может передавать твои заклинания касанием.', author_description='Это уже не временная стая помощников, а настоящий маленький маготехнический сотрудник: разведчик, курьер заклинаний и боевой спутник.', author_comment='Если чайник начал летать и отвечать телепатически — скорее всего, artificer снова работал без присмотра.', upcast='При сотворении ячейкой выше 2 уровень ячейки используется как уровень заклинания в характеристиках гомункула, увеличивая его параметры.', notes='Материальный компонент — самоцвет или кристалл стоимостью 100+ зм. Повторное сотворение заменяет уже существующего гомункула от этого заклинания.', casting_time='1 час или ритуал' where slug='homunculus-servant' and source_kind='official';

update public.spell_catalog set name_ru='Неподвижный предмет', effect_summary='Касаешься предмета весом не более 10 фунтов и магически фиксируешь его в пространстве на 1 час. Ты можешь назначить существ, способных двигать его нормально, и задать пароль, временно отключающий фиксацию. Остальные должны действием успешно пройти проверку Силы против Сл твоих заклинаний, чтобы сдвинуть предмет не более чем на 10 футов.', author_description='Обычная вещь внезапно решает, что координаты — часть её личности. Дверная ручка, ключ, сумка или кружка могут стать неожиданно фундаментальной частью архитектуры.', author_comment='Ничто не учит уважать магию так быстро, как кружка весом полкило, которую невозможно поднять.', upcast='Ячейкой 4–5 уровня длительность становится 24 часа; ячейкой 6 уровня или выше эффект длится, пока не будет рассеян.', notes='Материальный компонент — золотая пыль стоимостью 25 зм, которая расходуется. При сотворении можно определить существ и пароль, игнорирующие фиксацию.', casting_time='1 действие' where slug='immovable-object' and source_kind='official';

update public.spell_catalog set name_ru='Светящаяся монета Джима', effect_summary='Бросаешь монету в точку в пределах 60 футов; она ярко светится. Выбранные тобой существа в 30 футах от монеты делают спасбросок Мудрости. При провале на 1 минуту получают помеху на проверки Мудрости (Восприятие) и броски инициативы.', author_description='Джим доказал, что даже очень простой трюк становится заклинанием второго уровня, если добавить магию, налог и достаточно уверенную презентацию.', author_comment='Отвлекающий блестящий предмет. Технология древняя, результат стабильный.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Материальный компонент — монета; дополнительно расходуются 2 зм как лицензионный сбор. Эффект не требует концентрации.', casting_time='1 действие' where slug='jim-s-glowing-coin' and source_kind='official';

update public.spell_catalog set name_ru='Кинетическая прогулка', effect_summary='Бонусным действием усиливаешь движение до 1 минуты с концентрацией: скорость ходьбы увеличивается на 10 футов, ты не провоцируешь атаки и можешь проходить через пространства других существ без труднопроходимой местности. Если закончишь ход в чужом пространстве, тебя выбросит назад и ты получишь 1к8 урона силовым полем.', author_description='Магия превращает перемещение в танец, а поле боя — в место, где чужие клетки становятся проходами, а не стенами.', author_comment='Очень изящно, пока не закончил ход внутри орка. Тогда магия сама объяснит правила личного пространства.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Завершать ход в пространстве другого существа опасно: тебя перемещает в последнее свободное пространство и наносит 1к8 силового урона.', casting_time='1 бонусное действие' where slug='kinetic-jaunt' and source_kind='official';

update public.spell_catalog set name_ru='Земляная хватка Максимилиана', effect_summary='Из земли возникает рука размером 5 футов и хватает существо в своём пространстве. Цель делает спасбросок Силы; при провале получает 2к6 дробящего урона и становится Опутанной. В последующие ходы действием можно сжимать пленника, снова заставляя его спасаться от 2к6 урона, либо переместить руку и попытаться схватить другую цель.', author_description='Гигантская каменная рука решает сразу две задачи: держит врага на месте и периодически напоминает, почему выбраться стоило ещё в прошлом ходу.', author_comment='Максимилиан посмотрел на заклинание «удержание» и решил, что ему не хватает буквальной руки.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Пойманное существо может действием сделать проверку Силы против Сл твоих заклинаний и освободиться. Перемещение руки отпускает предыдущую цель.', casting_time='1 действие' where slug='maximilian-s-earthen-grasp' and source_kind='official';

update public.spell_catalog set name_ru='Шалость Натаира', effect_summary='Заполняешь видимый куб 20 футов фейско-драконьей магией на срок до 1 минуты с концентрацией. При сотворении и в начале каждого своего хода бросаешь к4: зона случайно очаровывает запахом пирога, ослепляет цветами, заставляет неудержимо хихикать и терять действие или становится труднопроходимой из-за патоки. Перед новым броском куб можно сдвинуть на 10 футов.', author_description='Заклинание честно называется шалостью: никто, включая заклинателя, не знает, чем именно помещение станет неудобным в следующий ход.', author_comment='Когда таблица случайных эффектов начинается с яблочного пирога, дальше обычно становится только хуже.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Эффект определяется к4 каждый раунд. Для разных результатов используются спасброски Мудрости или Ловкости; четвёртый результат просто делает область труднопроходимой.', casting_time='1 действие' where slug='nathair-s-mischief' and source_kind='official';

update public.spell_catalog set name_ru='Пиротехника', effect_summary='Выбираешь немагическое пламя, помещающееся в куб 5 футов, и гасишь его, создавая один из двух эффектов: вспышка заставляет существ в 10 футах пройти спасбросок Телосложения или ослепнуть до конца твоего следующего хода; дым создаёт сильно заслонённую сферу радиусом 20 футов на 1 минуту.', author_description='Любой обычный огонь можно превратить либо в ослепляющий фейерверк, либо в готовую дымовую завесу. Всё зависит от того, насколько незаметно ты планируешь уйти после шоу.', author_comment='Костёр был мирным до тех пор, пока волшебник не увидел в нём спецэффект.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Исходное пламя гаснет. Дым распространяется за углы и может быть рассеян сильным ветром. Заклинание не требует концентрации.', casting_time='1 действие' where slug='pyrotechnics' and source_kind='official';

update public.spell_catalog set name_ru='Связывающий лёд Рима', effect_summary='Выпускаешь 30-футовый конус ледяной энергии. Существа делают спасбросок Телосложения: при провале получают 3к8 холода и покрываются льдом, из-за чего их скорость становится 0; при успехе получают половину урона без обездвиживания. Пойманное существо или сосед может действием разбить лёд и снять ограничение.', author_description='Это не просто холодный конус — это способ превратить половину противников в очень сердитые ледяные статуи, пока они тратят действия на освобождение.', author_comment='Скорость ноль — один из самых убедительных аргументов не стоять перед драконом льда.', upcast='Урон увеличивается на 1к8 за каждый уровень ячейки выше 2.', notes='Лёд не требует концентрации после попадания. Освободить цель можно действием самой цели или другого существа в пределах досягаемости.', casting_time='1 действие' where slug='rime-s-binding-ice' and source_kind='official';

update public.spell_catalog set name_ru='Теневой клинок', effect_summary='Бонусным действием создаёшь в руке меч из сгущённой тени на срок до 1 минуты с концентрацией. Он наносит 2к8 психического урона, обладает свойствами лёгкого, фехтовального и метательного оружия (20/60 футов), а в тусклом свете или темноте атаки им совершаются с преимуществом.', author_description='Ты буквально хватаешь кусок темноты и начинаешь использовать его как аргумент ближнего боя. Особенно убедительно ночью.', author_comment='Если клинок сделан из тени, потерять его в темноте технически невозможно — он просто становится тематичнее.', upcast='Ячейкой 3–4 уровня урон становится 3к8, 5–6 уровня — 4к8, 7 уровня и выше — 5к8.', notes='Если выпустить клинок из руки, он исчезает в конце хода; пока заклинание действует, его можно снова создать бонусным действием.', casting_time='1 бонусное действие' where slug='shadow-blade' and source_kind='official';

update public.spell_catalog set name_ru='Небесная надпись', effect_summary='Формируешь до десяти слов из облаков в видимой части неба. Надпись сохраняется до 1 часа при концентрации и видна с большого расстояния, пока ветер или погода не рассеют облака.', author_description='Когда обычного сообщения мало, можно написать его буквально на небе. Трудно игнорировать записку размером с горизонт.', author_comment='Идеально для тайных сообщений, если тайну должны знать вообще все.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Можно сотворять ритуалом. Сильный ветер способен развеять надпись раньше окончания заклинания.', casting_time='1 действие или ритуал' where slug='skywrite' and source_kind='official';

update public.spell_catalog set name_ru='Рой снежков Сниллока', effect_summary='В точке в пределах 90 футов взрывается шквал ледяных снежков в сфере радиусом 5 футов. Существа в области делают спасбросок Ловкости, получая 3к6 урона холодом при провале или половину при успехе.', author_description='Да, это магический снежок. Нет, три к6 холода не делают его менее смешным — только менее безопасным.', author_comment='Сниллок доказал, что детская игра становится боевой магией после достаточного количества льда.', upcast='Урон увеличивается на 1к6 за каждый уровень ячейки выше 2.', notes='Область — небольшая сфера радиусом 5 футов; урон наносится мгновенно.', casting_time='1 действие' where slug='snilloc-s-snowball-swarm' and source_kind='official';

update public.spell_catalog set name_ru='Веер карт', effect_summary='Выпускаешь 15-футовый конус призрачных карт. Все существа в нём делают спасбросок Ловкости: при провале получают 2к10 урона силовым полем и ослепляются до конца своего следующего хода, при успехе получают половину урона без ослепления.', author_description='Карточный фокус, который заканчивается не аплодисментами, а силовым уроном и временной слепотой.', author_comment='Фраза «выбери карту» звучит гораздо тревожнее, когда колода призрачная.', upcast='Урон увеличивается на 1к10 за каждый уровень ячейки выше 2.', notes='Материальный компонент — колода карт. Ослепление применяется только при проваленном спасброске.', casting_time='1 действие' where slug='spray-of-cards' and source_kind='official';

update public.spell_catalog set name_ru='Призыв зверя', effect_summary='Призываешь звериный дух в свободное пространство в пределах 90 футов на срок до 1 часа с концентрацией. Выбираешь воздушную, наземную или водную форму; дух использует соответствующие свойства статблока, действует сразу после тебя и выполняет твои команды.', author_description='Универсальный магический зверь: летать, бегать или плавать — выбираешь форму под задачу, а не ищешь подходящее животное в ближайшем лесу.', author_comment='Природа по запросу, доставка за одно действие.', upcast='При использовании ячейки выше 2 уровень ячейки используется в характеристиках призванного духа, повышая его хиты, атаку и другие параметры статблока.', notes='Требуется концентрация. Для заклинания нужен материальный фокус — позолоченный желудь стоимостью 200+ зм; он не расходуется.', casting_time='1 действие' where slug='summon-beast' and source_kind='official';

update public.spell_catalog set name_ru='Ментальный хлыст Таши', effect_summary='Одно существо в пределах 90 футов делает спасбросок Интеллекта. При провале получает 3к6 психического урона, не может использовать реакции до конца своего следующего хода, а в следующий ход может выбрать только одно: перемещение, действие или бонусное действие. При успехе получает половину урона без ограничений.', author_description='Таша не останавливает противника полностью — она просто заставляет его мозг выбрать одну функцию из трёх и надеяться, что выбор был правильным.', author_comment='«Думай быстрее» — плохой совет, когда проблема именно в магическом хлысте по мозгу.', upcast='За каждый уровень ячейки выше 2 можно выбрать ещё одну цель; цели должны находиться не далее 30 футов друг от друга.', notes='Цель с проваленным спасброском не может совершать реакции и сильно ограничена в своём следующем ходу.', casting_time='1 действие' where slug='tasha-s-mind-whip' and source_kind='official';

update public.spell_catalog set name_ru='Вихревой перенос', effect_summary='Выбираешь существо в пределах 90 футов. Добровольная цель может автоматически согласиться, а недобровольная делает спасбросок Телосложения. При провале телепортируешь её в свободное пространство, которое видишь в пределах дистанции; место назначения должно безопасно поддерживать цель.', author_description='Телепортация, направленная не на себя, а на проблему. Союзника можно вытащить из беды, врага — поставить туда, где беда только начинается.', author_comment='Позиционирование становится намного проще, когда слово «иди» заменяется на «исчезни отсюда».', upcast='Дистанция заклинания увеличивается на 30 футов за каждый уровень ячейки выше 2.', notes='Нельзя поместить цель в пространство, которое её не вмещает, или в положение без подходящей опоры. Недобровольная цель получает спасбросок Телосложения.', casting_time='1 действие' where slug='vortex-warp' and source_kind='official';

update public.spell_catalog set name_ru='Оберегающий ветер', effect_summary='Сильный ветер кружит вокруг тебя в радиусе 10 футов до 10 минут с концентрацией. Он оглушительно шумит, гасит незащищённое пламя, рассеивает газы и испарения, делает область труднопроходимой для других существ и даёт помеху дальнобойным атакам оружием, проходящим через ветер.', author_description='Ты превращаешь себя в центр очень неудобной локальной погоды. Стрелки недовольны, дым уходит, свечи гаснут, разговоры становятся громче.', author_comment='Персональный вентилятор, которому выдали боевые характеристики.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Требуется концентрация. Ты и существа внутри ветра оглохшие из-за его шума; защищённые источники пламени могут сохраниться.', casting_time='1 действие' where slug='warding-wind' and source_kind='official';

update public.spell_catalog set name_ru='Чувство порталов', effect_summary='До 1 минуты с концентрацией ощущаешь любые порталы, даже неактивные, в пределах 30 футов. Обнаружив портал, можешь действием изучить его и сделать проверку своей заклинательной характеристики Сл 15; при успехе узнаёшь план назначения и необходимый ключ, после чего заклинание заканчивается.', author_description='Магический детектор дверей, которые могут быть невидимыми, закрытыми и вести буквально в другую реальность. Для Планскейпа — почти бытовой прибор.', author_comment='Когда город состоит из дверей, полезно хотя бы знать, какие из них настоящие порталы.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='При провале проверки этот портал нельзя изучать повторно тем же сотворением. Чувство блокируют 1 фут камня, 1 дюйм обычного металла, тонкий лист свинца или 3 фута дерева/земли.', casting_time='1 действие' where slug='warp-sense' and source_kind='official';

update public.spell_catalog set name_ru='Увядание и цветение', effect_summary='Выбираешь сферу радиусом 10 футов в пределах 60 футов. Выбранные существа в ней делают спасбросок Телосложения, получая 2к6 некротического урона при провале или половину при успехе. Одновременно одно выбранное существо в области может потратить Кость Хитов, бросить её и восстановить результат + модификатор твоей заклинательной характеристики.', author_description='Одной и той же волной ты высасываешь жизнь из одних существ и подталкиваешь другое к восстановлению. Некромантия с неожиданно бухгалтерским балансом.', author_comment='Редкое заклинание, которое одновременно говорит врагу «увядай», а союзнику — «цвети».', upcast='За каждый уровень ячейки выше 2 урон увеличивается на 1к6 и цель лечения может потратить ещё одну Кость Хитов.', notes='Ты сам выбираешь, какие существа получают некротический урон, и отдельно выбираешь одну цель для лечения в той же области.', casting_time='1 действие' where slug='wither-and-bloom' and source_kind='official';

update public.spell_catalog set name_ru='Карман на запястье', effect_summary='На срок до 1 часа с концентрацией создаёшь маленькое внепространственное хранилище. Можешь действием убрать из руки предмет весом до 5 фунтов в это пространство, а затем действием вернуть его в свободную руку; предмет можно снова прятать, пока заклинание действует.', author_description='Карман, которого физически нет. Отлично подходит для маленьких предметов, которые должны исчезнуть прямо сейчас и появиться тогда, когда это станет драматично.', author_comment='Наконец-то карман, из которого ключи не выпадают. Они просто существуют в другой геометрии.', upcast='Не усиливается при использовании ячейки более высокого уровня.', notes='Можно сотворять ритуалом. Когда заклинание заканчивается, спрятанный предмет появляется у твоих ног. Ограничение веса — 5 фунтов.', casting_time='1 действие или ритуал' where slug='wristpocket' and source_kind='official';

commit;